function createDialogPromise(opts, defaultValue, request, parseResponse) {
    if (opts?.signal?.aborted)
        return Promise.resolve(defaultValue);
    const id = crypto.randomUUID();
    return new Promise((resolve, reject) => {
        let timeoutId;
        const cleanup = () => {
            if (timeoutId)
                clearTimeout(timeoutId);
            opts?.signal?.removeEventListener("abort", onAbort);
            pendingExtensionRequests.delete(id);
        };
        const onAbort = () => {
            cleanup();
            resolve(defaultValue);
        };
        opts?.signal?.addEventListener("abort", onAbort, { once: true });
        if (opts?.timeout) {
            timeoutId = setTimeout(() => {
                cleanup();
                resolve(defaultValue);
            }, opts.timeout);
        }
        pendingExtensionRequests.set(id, {
            resolve: (response) => {
                cleanup();
                resolve(parseResponse(response));
            },
            reject,
        });
        output({ type: "extension_ui_request", id, ...request });
    });
}

const createExtensionUIContext = () => ({
    select: (title, options, opts) => createDialogPromise(opts, undefined, { method: "select", title, options, timeout: opts?.timeout }, (r) => "cancelled" in r && r.cancelled ? undefined : "value" in r ? r.value : undefined),
    confirm: (title, message, opts) => createDialogPromise(opts, false, { method: "confirm", title, message, timeout: opts?.timeout }, (r) => "cancelled" in r && r.cancelled ? false : "confirmed" in r ? r.confirmed : false),
    input: (title, placeholder, opts) => createDialogPromise(opts, undefined, { method: "input", title, placeholder, timeout: opts?.timeout }, (r) => "cancelled" in r && r.cancelled ? undefined : "value" in r ? r.value : undefined),
    notify(message, type) {
        // Fire and forget - no response needed
        output({
            type: "extension_ui_request",
            id: crypto.randomUUID(),
            method: "notify",
            message,
            notifyType: type,
        });
    },
    onTerminalInput() {
        // Raw terminal input not supported in RPC mode
        return () => { };
    },
    setStatus(key, text) {
        // Fire and forget - no response needed
        output({
            type: "extension_ui_request",
            id: crypto.randomUUID(),
            method: "setStatus",
            statusKey: key,
            statusText: text,
        });
    },
    setWorkingMessage(_message) {
        // Working message not supported in RPC mode - requires TUI loader access
    },
    setWorkingVisible(_visible) {
        // Working visibility not supported in RPC mode - requires TUI loader access
    },
    setWorkingIndicator(_options) {
        // Working indicator customization not supported in RPC mode - requires TUI loader access
    },
    setHiddenThinkingLabel(_label) {
        // Hidden thinking label not supported in RPC mode - requires TUI message rendering access
    },
    setWidget(key, content, options) {
        // Only support string arrays in RPC mode - factory functions are ignored
        if (content === undefined || Array.isArray(content)) {
            output({
                type: "extension_ui_request",
                id: crypto.randomUUID(),
                method: "setWidget",
                widgetKey: key,
                widgetLines: content,
                widgetPlacement: options?.placement,
            });
        }
        // Component factories are not supported in RPC mode - would need TUI access
    },
    setFooter(_factory) {
        // Custom footer not supported in RPC mode - requires TUI access
    },
    setHeader(_factory) {
        // Custom header not supported in RPC mode - requires TUI access
    },
    setTitle(title) {
        // Fire and forget - host can implement terminal title control
        output({
            type: "extension_ui_request",
            id: crypto.randomUUID(),
            method: "setTitle",
            title,
        });
    },
    async custom() {
        // Custom UI not supported in RPC mode
        return undefined;
    },
    pasteToEditor(text) {
        // Paste handling not supported in RPC mode - falls back to setEditorText
        this.setEditorText(text);
    },
    setEditorText(text) {
        // Fire and forget - host can implement editor control
        output({
            type: "extension_ui_request",
            id: crypto.randomUUID(),
            method: "set_editor_text",
            text,
        });
    },
    getEditorText() {
        // Synchronous method can't wait for RPC response
        // Host should track editor state locally if needed
        return "";
    },
    async editor(title, prefill) {
        const id = crypto.randomUUID();
        return new Promise((resolve, reject) => {
            pendingExtensionRequests.set(id, {
                resolve: (response) => {
                    if ("cancelled" in response && response.cancelled) {
                        resolve(undefined);
                    }
                    else if ("value" in response) {
                        resolve(response.value);
                    }
                    else {
                        resolve(undefined);
                    }
                },
                reject,
            });
            output({ type: "extension_ui_request", id, method: "editor", title, prefill });
        });
    },
    addAutocompleteProvider() {
        // Autocomplete provider composition is not supported in RPC mode
    },
    setEditorComponent() {
        // Custom editor components not supported in RPC mode
    },
    getEditorComponent() {
        // Custom editor components not supported in RPC mode
        return undefined;
    },
    get theme() {
        return theme;
    },
    getAllThemes() {
        return [];
    },
    getTheme(_name) {
        return undefined;
    },
    setTheme(_theme) {
        // Theme switching not supported in RPC mode
        return { success: false, error: "Theme switching not supported in RPC mode" };
    },
    getToolsExpanded() {
        // Tool expansion not supported in RPC mode - no TUI
        return false;
    },
    setToolsExpanded(_expanded) {
        // Tool expansion not supported in RPC mode - no TUI
    },
});

case "prompt": {
    // Start prompt handling immediately, but emit the authoritative response only after
    // prompt preflight succeeds. Queued and immediately handled prompts also count as success.
    let preflightSucceeded = false;
    void session
        .prompt(command.message, {
        images: command.images,
        streamingBehavior: command.streamingBehavior,
        source: "rpc",
        preflightResult: (disposition) => {
            preflightSucceeded = true;
            output(success(id, "prompt", { disposition }));
        },
    })
        .catch((e) => {
        if (!preflightSucceeded) {
            output(error(id, "prompt", e.message));
        }
    });
    return undefined;
}

case "abort": {
    await session.abort();
    return success(id, "abort");
}

case "get_state": {
    const state = {
        model: session.model,
        thinkingLevel: session.thinkingLevel,
        isStreaming: session.isStreaming,
        isCompacting: session.isCompacting,
        steeringMode: session.steeringMode,
        followUpMode: session.followUpMode,
        sessionFile: session.sessionFile,
        sessionId: session.sessionId,
        sessionName: session.sessionName,
        autoCompactionEnabled: session.autoCompactionEnabled,
        messageCount: session.messages.length,
        pendingMessageCount: session.pendingMessageCount,
    };
    return success(id, "get_state", state);
}

case "get_session_stats": {
    const stats = session.getSessionStats();
    return success(id, "get_session_stats", stats);
}

if (typeof parsed === "object" &&
    parsed !== null &&
    "type" in parsed &&
    parsed.type === "extension_ui_response") {
    const response = parsed;
    const pending = pendingExtensionRequests.get(response.id);
    if (pending) {
        pendingExtensionRequests.delete(response.id);
        pending.resolve(response);
    }
    return;
}

unsubscribe = session.subscribe((event) => {
    output(toJsonEvent(event));
    if (event.type === "agent_settled") {
        void checkShutdownRequested();
    }
});

getContextUsage() {
    const model = this._limitsModel();
    if (!model)
        return undefined;
    const contextWindow = model.contextWindow ?? 0;
    if (contextWindow <= 0)
        return undefined;
    // After compaction, the last assistant usage reflects pre-compaction context size.
    // We can only trust usage from an assistant that responded after the latest compaction.
    // If no such assistant exists, context token count is unknown until the next LLM response.
    const projection = this.sessionManager.buildSessionProjection();
    const branch = this.sessionManager.getBranch();
    const latestCompaction = getLatestCompactionEntry(branch);
    if (latestCompaction) {
        const projectedAssistants = new Set(projection.entries.flatMap((entry) => entry.messages.some((message) => message.role === "assistant" &&
            message.stopReason !== "aborted" &&
            message.stopReason !== "error" &&
            calculateContextTokens(message.usage) > 0)
            ? [entry.sourceEntry.id]
            : []));
        const compactionIndex = branch.findIndex((entry) => entry.id === latestCompaction.id);
        const hasPostCompactionUsage = branch
            .slice(compactionIndex + 1)
            .some((entry) => projectedAssistants.has(entry.id));
        if (!hasPostCompactionUsage)
            return { tokens: null, contextWindow, percent: null };
    }
    const estimate = estimateProjectedContextTokens(projection, branch);
    const percent = (estimate.tokens / contextWindow) * 100;
    return {
        tokens: estimate.tokens,
        contextWindow,
        percent,
    };
}

getSessionStats() {
    let userMessages = 0;
    let assistantMessages = 0;
    let toolResults = 0;
    let totalMessages = 0;
    let toolCalls = 0;
    const usageTotals = createUsageTotals();
    for (const entry of this.sessionManager.getEntries()) {
        if (entry.type === "usage") {
            addUsageToTotals(usageTotals, entry.usage);
        }
        else if ((entry.type === "branch_summary" || entry.type === "compaction") && entry.usage) {
            addUsageToTotals(usageTotals, entry.usage);
        }
        if (entry.type !== "message")
            continue;
        totalMessages++;
        const message = entry.message;
        if (message.role === "user") {
            userMessages++;
        }
        else if (message.role === "toolResult") {
            toolResults++;
            if (message.usage) {
                addUsageToTotals(usageTotals, message.usage);
            }
        }
        else if (message.role === "assistant") {
            assistantMessages++;
            const assistantMsg = message;
            if (Array.isArray(assistantMsg.content)) {
                toolCalls += assistantMsg.content.filter((c) => c.type === "toolCall").length;
            }
            addUsageToTotals(usageTotals, assistantMsg.usage);
        }
    }
    return {
        sessionFile: this.sessionFile,
        sessionId: this.sessionId,
        userMessages,
        assistantMessages,
        toolCalls,
        toolResults,
        totalMessages,
        tokens: {
            input: usageTotals.input,
            output: usageTotals.output,
            cacheRead: usageTotals.cacheRead,
            cacheWrite: usageTotals.cacheWrite,
            total: usageTotals.input + usageTotals.output + usageTotals.cacheRead + usageTotals.cacheWrite,
        },
        cost: usageTotals.cost,
        contextUsage: this.getContextUsage(),
    };
}

_limitsModel() {
    return this.routedModel?.model ?? this.model;
}

export function calculateContextTokens(usage) {
    return usage.totalTokens || usage.input + usage.output + usage.cacheRead + usage.cacheWrite;
}

export interface ContextUsage {
    /** Estimated context tokens, or null if unknown (e.g. right after compaction, before next LLM response). */
    tokens: number | null;
    contextWindow: number;
    /** Context usage as percentage of context window, or null if tokens is unknown. */
    percent: number | null;
}

